/* IGCSE 商业研究题库扩充 */
window.IGCSE_QUESTIONS = (window.IGCSE_QUESTIONS || []).concat([
  /* ============ 市场与营销 Marketing（bus_q007 ~ bus_q043，共37题） ============ */
  { "id":"bus_q007","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"营销组合 4P 中的「Place（渠道）」主要指什么？","type":"choice","options":["产品在门店货架上的摆放位置","把产品送达目标客户的分销与物流渠道","产品的定价地点","广告投放的地理位置"],"answer":"把产品送达目标客户的分销与物流渠道","explain":"Place 关注分销渠道与物流，即如何让目标客户方便买到产品；它指的不是门店陈列位置。","tags":["marketing","place"],"xpReward":10 },
  { "id":"bus_q008","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"企业经过市场细分后，决定重点服务的那一个或几个群体，称为？","type":"choice","options":["市场细分","目标市场 Target market","市场定位","大众市场"],"answer":"目标市场 Target market","explain":"细分是把市场拆开，目标市场是企业选择要服务的群体，定位则是在该群体心中树立形象。","tags":["marketing","target"],"xpReward":10 },
  { "id":"bus_q009","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"企业在目标顾客心目中为产品树立独特形象（如「高端」「性价比高」），这属于？","type":"choice","options":["市场定位 Positioning","市场调研","市场渗透","分销渠道"],"answer":"市场定位 Positioning","explain":"定位是让产品在顾客心智中占据差异化位置，常通过价格、品质和品牌形象来实现。","tags":["marketing","positioning"],"xpReward":10 },
  { "id":"bus_q010","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"企业为当前特定目的亲自收集的数据（如现场问卷、访谈），称为？","type":"choice","options":["二手数据 Secondary data","一手数据 Primary data","内部历史数据","公开统计数据"],"answer":"一手数据 Primary data","explain":"一手数据是企业直接为本次调研收集的；二手数据是他人已经收集好的现成资料。","tags":["marketing","research"],"xpReward":10 },
  { "id":"bus_q011","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"下列哪一项属于二手数据（Secondary data）？","type":"choice","options":["在自家门店随机拦访顾客","查阅政府发布的行业统计报告","向消费者发放新问卷","组织焦点小组讨论"],"answer":"查阅政府发布的行业统计报告","explain":"政府报告、行业年鉴、已有研究都是现成的二手数据；拦访、问卷、焦点小组都属于一手数据。","tags":["marketing","research"],"xpReward":10 },
  { "id":"bus_q012","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"一家奶茶店想了解本店顾客偏好，随机请进店顾客填写问卷。该数据属于？","type":"choice","options":["二手数据，因为顾客本来就在店里","一手数据，为本次目的直接收集","内部数据，无需分类","外部公开数据"],"answer":"一手数据，为本次目的直接收集","explain":"为特定目的直接向受访者收集即为一手数据；顾客是否来自店内并不改变其性质。","tags":["marketing","research"],"xpReward":10 },
  { "id":"bus_q013","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"某新上市高端耳机定价远高于同类产品，只为赚取愿意早买的高收入顾客。这属于？","type":"choice","options":["渗透定价","撇脂定价 Skimming","成本加成定价","竞争性定价"],"answer":"撇脂定价 Skimming","explain":"撇脂定价以高价格先「撇走」愿付高价的早期顾客，常见于有专利或新颖的科技产品。","tags":["marketing","pricing"],"xpReward":10 },
  { "id":"bus_q014","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"企业在单位成本基础上加上一个固定百分比利润来定价，称为？","type":"choice","options":["成本加成定价 Cost-plus","撇脂定价","渗透定价","拍卖定价"],"answer":"成本加成定价 Cost-plus","explain":"成本加成＝单位成本×（1＋加成率），简单易行，但忽略了市场需求与竞争。","tags":["marketing","pricing"],"xpReward":10 },
  { "id":"bus_q015","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"加油站主要参照附近竞争对手的价格来定价，这种方法是？","type":"choice","options":["成本加成定价","竞争性定价 Competition-based","撇脂定价","渗透定价"],"answer":"竞争性定价 Competition-based","explain":"在同质、信息透明的市场（如汽油）中，企业多跟随竞争对手定价。","tags":["marketing","pricing"],"xpReward":10 },
  { "id":"bus_q016","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"下列哪一项最典型地属于「广告 Advertising」？","type":"choice","options":["企业付费在电视上播出产品宣传片","给老顾客发优惠券","记者报道企业的公益活动","销售员上门演示产品"],"answer":"企业付费在电视上播出产品宣传片","explain":"广告是付费、非人员的大众传播；优惠券是销售促进，媒体报道是公关，上门演示是人员推销。","tags":["marketing","promotion"],"xpReward":10 },
  { "id":"bus_q017","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"「买一送一」「限时优惠券」「满减活动」主要属于促销组合中的？","type":"choice","options":["公共关系","销售促进 Sales promotion","直销","广告"],"answer":"销售促进 Sales promotion","explain":"销售促进是短期激励手段，目的是刺激即时购买；效果短但见效快。","tags":["marketing","promotion"],"xpReward":10 },
  { "id":"bus_q018","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"企业通过媒体报道、新闻发布会树立正面形象，而不直接为版面付费。这属于？","type":"choice","options":["广告","公共关系 Public relations","销售促进","人员推销"],"answer":"公共关系 Public relations","explain":"公关以第三方媒体传播，可信度高但企业控制力弱；广告则是付费、可控的。","tags":["marketing","promotion"],"xpReward":10 },
  { "id":"bus_q019","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"企业通过邮件、短信、社群账号直接向特定顾客发送产品信息，属于？","type":"choice","options":["直销 Direct marketing","大众广告","公共关系","街头促销"],"answer":"直销 Direct marketing","explain":"直销跳过中间渠道、直接与目标顾客沟通，可精准投放并衡量效果。","tags":["marketing","promotion"],"xpReward":10 },
  { "id":"bus_q020","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"品牌官网直接向消费者销售产品、不经过任何中间商，这属于？","type":"choice","options":["间接渠道","直接渠道 Direct channel","批发渠道","零售渠道"],"answer":"直接渠道 Direct channel","explain":"直接渠道＝生产商直达顾客（官网、直营店）；间接渠道则经批发商、零售商等中间商。","tags":["marketing","place"],"xpReward":10 },
  { "id":"bus_q021","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"处于分销渠道末端、直接把产品卖给最终消费者的中间商是？","type":"choice","options":["批发商","零售商 Retailer","代理商","生产商"],"answer":"零售商 Retailer","explain":"零售商面向最终顾客（超市、网店）；批发商主要向零售商或商家批量供货。","tags":["marketing","place"],"xpReward":10 },
  { "id":"bus_q022","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"产品刚上市、销量低、单位成本高、几乎没有利润，处于产品生命周期的？","type":"choice","options":["引入期 Introduction","成长期","成熟期","衰退期"],"answer":"引入期 Introduction","explain":"引入期需大量推广、销量小、成本高，企业通常亏损或微利。","tags":["marketing","lifecycle"],"xpReward":10 },
  { "id":"bus_q023","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"产品销量快速上升、利润增加、竞争者开始涌入，处于生命周期的？","type":"choice","options":["引入期","成长期 Growth","成熟期","衰退期"],"answer":"成长期 Growth","explain":"成长期认知度提高、销量与利润上升，吸引更多竞争者进入。","tags":["marketing","lifecycle"],"xpReward":10 },
  { "id":"bus_q024","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"销量达到顶峰后趋于平稳、竞争激烈、利润增速放缓，属于生命周期的？","type":"choice","options":["引入期","成长期","成熟期 Maturity","衰退期"],"answer":"成熟期 Maturity","explain":"成熟期市场饱和、价格竞争加剧，企业靠差异化和成本控制维持利润。","tags":["marketing","lifecycle"],"xpReward":10 },
  { "id":"bus_q025","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"某功能手机因智能手机普及而销量和利润持续下滑，处于生命周期的？","type":"choice","options":["引入期","成长期","成熟期","衰退期 Decline"],"answer":"衰退期 Decline","explain":"衰退期销量下滑，企业可选择收割、放弃或重新定位产品。","tags":["marketing","lifecycle"],"xpReward":10 },
  { "id":"bus_q026","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"顾客反复购买同一品牌、不易被竞品吸引，这种现象称为？","type":"choice","options":["品牌忠诚度 Brand loyalty","价格弹性","市场细分","规模经济"],"answer":"品牌忠诚度 Brand loyalty","explain":"品牌忠诚降低营销成本、形成重复购买，是重要的竞争壁垒。","tags":["marketing","brand"],"xpReward":10 },
  { "id":"bus_q027","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"强品牌（品牌资产高）通常能为企业带来的好处是？","type":"choice","options":["可以完全忽略竞争对手","顾客愿付更高价格、新品更容易被接受","无需做任何市场调研","产品永远不会进入衰退期"],"answer":"顾客愿付更高价格、新品更容易被接受","explain":"品牌资产带来溢价、信任和延伸优势，但不能消除竞争或风险。","tags":["marketing","brand"],"xpReward":10 },
  { "id":"bus_q028","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"一家小公司专注服务「左撇子专业文具」这一很小的细分市场，属于？","type":"choice","options":["大众营销 Mass marketing","利基营销 Niche marketing","无差别营销","出口营销"],"answer":"利基营销 Niche marketing","explain":"利基营销服务小众、特定需求的细分市场，竞争弱、利润高，但市场容量有限。","tags":["marketing","segmentation"],"xpReward":10 },
  { "id":"bus_q029","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"按年龄、性别、收入、职业、家庭规模划分市场，属于哪种细分变量？","type":"choice","options":["人口细分 Demographic","地理细分","心理细分","行为细分"],"answer":"人口细分 Demographic","explain":"人口统计特征最易测量、最常用；心理细分则看生活方式与价值观。","tags":["marketing","segmentation"],"xpReward":10 },
  { "id":"bus_q030","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"按生活方式、价值观、社会阶层、个性来划分消费者，属于？","type":"choice","options":["地理细分","心理细分 Psychographic","人口细分","行为细分"],"answer":"心理细分 Psychographic","explain":"心理细分关注「为什么买」，常与人口、地理变量结合使用。","tags":["marketing","segmentation"],"xpReward":10 },
  { "id":"bus_q031","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"按国家、地区、城市规模、气候来划分市场，属于？","type":"choice","options":["地理细分 Geographic","人口细分","行为细分","心理细分"],"answer":"地理细分 Geographic","explain":"地理细分适用于需求随地区差异明显的产品，例如不同气候地区的服装。","tags":["marketing","segmentation"],"xpReward":10 },
  { "id":"bus_q032","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"按使用频率、追求的利益、品牌忠诚度、使用时机划分市场，属于？","type":"choice","options":["地理细分","人口细分","行为细分 Behavioral","心理细分"],"answer":"行为细分 Behavioral","explain":"行为细分基于消费者实际购买和使用行为，对设计促销最直接。","tags":["marketing","segmentation"],"xpReward":10 },
  { "id":"bus_q033","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"市场调研中从全体目标顾客中抽取一部分进行调查，这部分被调查者称为？","type":"choice","options":["总体 Population","样本 Sample","对照组","中间商"],"answer":"样本 Sample","explain":"总体是全部目标顾客，样本是其中被实际调查的一部分；样本要具有代表性。","tags":["marketing","research"],"xpReward":10 },
  { "id":"bus_q034","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"电视、户外广告牌等大众广告最突出的优点是？","type":"choice","options":["能与每位顾客深度互动","覆盖面广、迅速建立品牌知名度","成本极低","可以精准只触达一个人"],"answer":"覆盖面广、迅速建立品牌知名度","explain":"大众广告覆盖面广但成本高、无法精准；精准互动是直销和数字营销的优势。","tags":["marketing","promotion"],"xpReward":10 },
  { "id":"bus_q035","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"渗透定价要成功，下列哪一个条件最关键？","type":"choice","options":["市场对价格高度敏感、低价能带来大量销量","产品有独特专利、顾客愿付高价","市场几乎没有竞争者","生产成本极高"],"answer":"市场对价格高度敏感、低价能带来大量销量","explain":"渗透定价依赖价格敏感和规模效应；若顾客不敏感或成本降不下来则难以为继。","tags":["marketing","pricing"],"xpReward":10 },
  { "id":"bus_q036","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"营销组合中「Product（产品）」决策通常不包括下列哪一项？","type":"choice","options":["产品功能与质量","品牌与包装","售后服务","产品在货架上打几折"],"answer":"产品在货架上打几折","explain":"打折属于 Price 或 Promotion 决策；产品决策关注功能、质量、品牌、包装与服务。","tags":["marketing","product"],"xpReward":10 },
  { "id":"bus_q037","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"企业大力说服零售商进货、把产品「推」向渠道，这种策略称为？","type":"choice","options":["推动策略 Push strategy","拉动策略 Pull strategy","撇脂策略","利基策略"],"answer":"推动策略 Push strategy","explain":"推动靠渠道力量铺货；拉动靠广告刺激最终消费者主动向门店索要产品。","tags":["marketing","promotion"],"xpReward":10 },
  { "id":"bus_q038","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"请解释：一家准备推出新饮品的小企业，为什么在投产前做市场调研很重要？","type":"essay","options":[],"answer":"市场调研可在投入大量资金前了解：目标顾客是谁、他们的口味与价格接受度、现有竞品的优缺点、合适的定价与渠道，从而降低失败风险、提高产品命中率。","explain":"评分要点：①识别目标顾客与需求；②评估竞品与市场缺口；③为定价、产品设计和推广提供依据；④减少盲目投资、降低商业风险。答出任3点即可给分。","tags":["marketing","research"],"xpReward":5 },
  { "id":"bus_q039","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"对比撇脂定价（skimming）与渗透定价（penetration pricing），分别说明各适合什么情形。","type":"essay","options":[],"answer":"撇脂定价：上市初期定高价，适合新颖、有专利或品牌强、顾客对价格不敏感、可逐步降价的产品（如新款科技产品），目的是快速收回研发成本。渗透定价：上市初期定低价，适合价格敏感、竞争激烈、靠走量和规模效应降本的市场，目的是快速抢占份额。","explain":"评分要点：①两种策略的定义；②撇脂适用：新颖/专利/价格不敏感/回收成本；③渗透适用：价格敏感/竞争激烈/规模效应/抢份额；④能结合一例说明更佳。","tags":["marketing","pricing"],"xpReward":5 },
  { "id":"bus_q040","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"解释品牌价值（brand equity）能为企业带来哪些好处。","type":"essay","options":[],"answer":"强品牌带来：顾客忠诚度高、重复购买；顾客愿付溢价；新产品（品牌延伸）更容易被接受；渠道更愿意合作；在竞争中形成壁垒、降低价格战压力。","explain":"评分要点：①品牌忠诚与重复购买；②溢价能力；③品牌延伸/新品接受度；④渠道议价与竞争壁垒。答出任3点给分，并能结合例子更佳。","tags":["marketing","brand"],"xpReward":5 },
  { "id":"bus_q041","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"产品进入成熟期后，销量增长放缓。请列举企业可采取的两种应对策略并简要说明。","type":"essay","options":[],"answer":"可采取：①市场改良——寻找新顾客或新用途、开拓新地区；②产品改良——改进质量、功能或外观以吸引注意；③营销组合改良——调整价格、促销或渠道。目的是延长成熟期、延缓衰退。","explain":"评分要点：能写出市场改良、产品改良、营销组合改良中任意两项并简要解释即可；说明其目的（维持销量/利润）更佳。","tags":["marketing","lifecycle"],"xpReward":5 },
  { "id":"bus_q042","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"讨论大众营销（mass marketing）与利基营销（niche marketing）各自的优缺点。","type":"essay","options":[],"answer":"大众营销：用一套产品面向整个市场，优点是规模大、单位成本低；缺点是竞争激烈、难以满足差异化需求。利基营销：服务小众细分市场，优点是竞争弱、顾客忠诚、可定高价；缺点是市场容量小、增长受限、易受需求波动影响。","explain":"评分要点：①大众营销优（规模/低成本）与劣（竞争/无差异）；②利基营销优（竞争弱/忠诚/溢价）与劣（容量小/风险集中）。能对比分析给满分。","tags":["marketing","segmentation"],"xpReward":5 },
  { "id":"bus_q043","exam_board":"CIE","subject":"business","chapter":"Marketing","topicId":"bus_marketing","question":"解释企业为什么要进行市场细分（segmentation），而不是对所有顾客卖同样的东西。","type":"essay","options":[],"answer":"不同顾客在需求、收入、偏好上差异很大。市场细分帮助企业：更精准识别需求、集中资源服务最有价值的群体、设计更合适的产品与营销组合、提高竞争力和顾客满意度，避免「一刀切」造成的资源浪费。","explain":"评分要点：①顾客需求存在差异；②精准定位目标市场；③优化产品、定价与促销；④提高资源利用效率与竞争优势。答出任3点给分。","tags":["marketing","segmentation"],"xpReward":5 },

  /* ============ 财务基础 Finance（bus_q044 ~ bus_q080，共37题） ============ */
  { "id":"bus_q044","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"若产品单价 50 元，本月售出 200 件，则销售收入（revenue）是？","type":"choice","options":["10000 元","250 元","4000 元","1000 元"],"answer":"10000 元","explain":"收入＝单价×销量＝50×200＝10000 元。","tags":["finance","revenue"],"xpReward":10 },
  { "id":"bus_q045","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业的总成本（total costs）等于？","type":"choice","options":["固定成本＋变动成本","单价×销量","利润＋税收","固定成本－变动成本"],"answer":"固定成本＋变动成本","explain":"总成本＝固定成本（不随产量变）＋变动成本（随产量变）。","tags":["finance","costs"],"xpReward":10 },
  { "id":"bus_q046","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"下列哪一项属于固定成本（fixed cost）？","type":"choice","options":["按件支付的包装材料费","每月固定的厂房租金","随产量增加的超额电费","计件工人工资"],"answer":"每月固定的厂房租金","explain":"租金、固定工资、设备折旧在短期内不随产量变化；材料、计件工资随产量变化。","tags":["finance","costs"],"xpReward":10 },
  { "id":"bus_q047","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"电费既有每月固定的基础费用、又有用得越多越贵的部分，这种成本属于？","type":"choice","options":["纯固定成本","纯变动成本","半变动成本 Semi-variable","沉没成本"],"answer":"半变动成本 Semi-variable","explain":"半变动成本＝固定部分＋随用量变动的部分，如含基础月租的水电和电话费。","tags":["finance","costs"],"xpReward":10 },
  { "id":"bus_q048","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"某产品单价 40 元，单位变动成本 24 元，固定成本 6400 元。盈亏平衡销量是？","type":"choice","options":["200 件","267 件","400 件","160 件"],"answer":"400 件","explain":"贡献毛益＝40－24＝16 元；$BEP=\\frac{6400}{16}=400$ 件。","tags":["finance","bep"],"xpReward":10 },
  { "id":"bus_q049","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"单位贡献毛益（contribution per unit）等于？","type":"choice","options":["单价－单位变动成本","单价－单位固定成本","单价－总成本","固定成本÷销量"],"answer":"单价－单位变动成本","explain":"贡献毛益＝价格－单位变动成本，用来先抵补固定成本，之后才是利润。","tags":["finance","bep"],"xpReward":10 },
  { "id":"bus_q050","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"某产品单位贡献毛益为 20 元，固定成本 5000 元。要达到盈亏平衡需销售多少件？","type":"choice","options":["200 件","250 件","500 件","1000 件"],"answer":"250 件","explain":"盈亏平衡销量＝固定成本÷单位贡献毛益＝5000÷20＝250 件。","tags":["finance","bep"],"xpReward":10 },
  { "id":"bus_q051","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"在盈亏平衡图（break-even chart）上，从纵轴某一固定金额出发、不经过原点的那条线是？","type":"choice","options":["总收入线","总成本线（含固定成本截距）","利润线","固定成本为零线"],"answer":"总成本线（含固定成本截距）","explain":"总成本线从固定成本额处出发、向右上方倾斜；总收入线从原点出发。","tags":["finance","bep"],"xpReward":10 },
  { "id":"bus_q052","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"盈亏平衡图上，总收入线与总成本线相交的点代表？","type":"choice","options":["利润最大点","盈亏平衡点 BEP","固定成本点","最大产能点"],"answer":"盈亏平衡点 BEP","explain":"交点处收入＝总成本，既不盈利也不亏损；交点左侧亏损、右侧盈利。","tags":["finance","bep"],"xpReward":10 },
  { "id":"bus_q053","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业实际销量超出盈亏平衡销量的部分，称为？","type":"choice","options":["安全边际 Margin of safety","贡献毛益","固定成本","折旧"],"answer":"安全边际 Margin of safety","explain":"安全边际＝实际（或预算）销量－盈亏平衡销量，越大说明企业越抗风险。","tags":["finance","bep"],"xpReward":10 },
  { "id":"bus_q054","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"固定成本 3000 元，单位贡献毛益 15 元。若想获得 1500 元目标利润，需销售多少件？","type":"choice","options":["200 件","300 件","150 件","450 件"],"answer":"300 件","explain":"目标利润销量＝（固定成本＋目标利润）÷单位贡献毛益＝（3000＋1500）÷15＝300 件。","tags":["finance","bep"],"xpReward":10 },
  { "id":"bus_q055","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"营运资本（working capital）等于？","type":"choice","options":["流动资产－流动负债","总资产－总负债","收入－成本","固定资产－贷款"],"answer":"流动资产－流动负债","explain":"营运资本＝流动资产－流动负债，反映企业短期偿债与日常周转能力。","tags":["finance","working"],"xpReward":10 },
  { "id":"bus_q056","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业为应付短期周转困难、随时可借还的银行透支（overdraft）属于？","type":"choice","options":["长期资金来源","短期资金来源","股权融资","留存利润"],"answer":"短期资金来源","explain":"透支、短期贷款、应付账款都是短期融资，用于补现金流缺口而非长期投资。","tags":["finance","sources"],"xpReward":10 },
  { "id":"bus_q057","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业向银行借入期限 5 年、分期还本付息的款项，属于？","type":"choice","options":["短期融资","长期银行贷款（债务融资）","股权融资","商业信用"],"answer":"长期银行贷款（债务融资）","explain":"中长期贷款需还本付息、利息可税前扣除，但要按期还款并有违约风险。","tags":["finance","sources"],"xpReward":10 },
  { "id":"bus_q058","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"股份公司向投资者出售新股募集资金、不还本但要分享利润，这种方式是？","type":"choice","options":["银行贷款","股权融资 Share capital","银行透支","融资租赁"],"answer":"股权融资 Share capital","explain":"股权融资无需还本、风险较低，但会稀释原股东控制权并需分红。","tags":["finance","sources"],"xpReward":10 },
  { "id":"bus_q059","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"下列哪一项是使用留存利润（retained profit）作为资金来源的主要优点？","type":"choice","options":["必须对外还本付息","无需还本、不稀释股权、成本低","一定会分散股东控制权","必须公开招股说明书"],"answer":"无需还本、不稀释股权、成本低","explain":"留存利润是企业积累的自有资金，方便灵活；缺点是规模受当期盈利限制。","tags":["finance","sources"],"xpReward":10 },
  { "id":"bus_q060","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业按贷款合同每月固定支付的利息，通常应归类为？","type":"choice","options":["变动成本","固定成本","半变动成本","直接材料成本"],"answer":"固定成本","explain":"约定的利息额不随产量变化，属于固定的财务费用。","tags":["finance","costs"],"xpReward":10 },
  { "id":"bus_q061","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"损益表中，销售收入减去销售成本（COGS）得到的是？","type":"choice","options":["净利润","毛利 Gross profit","营业利润","营运资本"],"answer":"毛利 Gross profit","explain":"毛利＝收入－直接销售成本；再减去各项费用和税才得到净利润。","tags":["finance","accounts"],"xpReward":10 },
  { "id":"bus_q062","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业最终税后、可分配给股东的利润称为？","type":"choice","options":["毛利","净利润 Net profit","总收入","贡献毛益"],"answer":"净利润 Net profit","explain":"净利润＝收入－所有成本、费用、利息和税，是真正赚到的钱。","tags":["finance","accounts"],"xpReward":10 },
  { "id":"bus_q063","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"下列哪一项属于资产负债表中的流动资产（current asset）？","type":"choice","options":["厂房","银行存款","长期银行贷款","未分配利润"],"answer":"银行存款","explain":"现金、银行存款、应收账款、存货都是一年内可变现的流动资产。","tags":["finance","accounts"],"xpReward":10 },
  { "id":"bus_q064","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"下列哪一项属于流动负债（current liability）？","type":"choice","options":["应付给供应商的货款（一年内）","厂房设备","股东投入的资本","长期债券"],"answer":"应付给供应商的货款（一年内）","explain":"应付账款、短期借款、一年内到期的负债是流动负债，需在短期内偿还。","tags":["finance","accounts"],"xpReward":10 },
  { "id":"bus_q065","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业拥有并长期使用、不打算在一年内出售的资产（如厂房、机器）属于？","type":"choice","options":["流动资产","固定资产 Non-current asset","流动负债","营运资本"],"answer":"固定资产 Non-current asset","explain":"固定资产供长期生产使用，如土地、厂房、设备，并会逐年计提折旧。","tags":["finance","accounts"],"xpReward":10 },
  { "id":"bus_q066","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"机器设备随使用年限逐年分摊其成本，这种会计处理称为？","type":"choice","options":["折旧 Depreciation","摊销商誉","计提坏账","提取公积金"],"answer":"折旧 Depreciation","explain":"固定资产价值随损耗递减，通过折旧分摊到各期成本中。","tags":["finance","accounts"],"xpReward":10 },
  { "id":"bus_q067","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"许多盈利企业最终倒闭，最常见的直接原因是？","type":"choice","options":["利润太高","现金流断裂、发不出工资和货款","缴纳的税太少","产品品种太多"],"answer":"现金流断裂、发不出工资和货款","explain":"账面盈利但钱收不回、付不出，即现金流断裂，是中小企业猝死的主因。","tags":["finance","cashflow"],"xpReward":10 },
  { "id":"bus_q068","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"下列哪一项属于现金流入（cash inflow）？","type":"choice","options":["支付原材料货款","客户支付赊销货款","缴纳所得税","支付员工工资"],"answer":"客户支付赊销货款","explain":"收到客户的钱、获得贷款、股东出资是现金流入；付款、缴税、发工资是流出。","tags":["finance","cashflow"],"xpReward":10 },
  { "id":"bus_q069","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"下列哪一项属于现金流出（cash outflow）？","type":"choice","options":["客户预付货款","获得银行贷款","购买新设备支付的款项","股东追加投资"],"answer":"购买新设备支付的款项","explain":"买设备、进货、发工资、还贷付息都会使现金减少。","tags":["finance","cashflow"],"xpReward":10 },
  { "id":"bus_q070","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"已经向客户发货、但客户尚未付款的金额，在账上记为？","type":"choice","options":["应付账款","应收账款 Debtors（trade receivables）","存货","固定资产"],"answer":"应收账款 Debtors（trade receivables）","explain":"应收账款是客户欠企业的钱，属流动资产；收不回会形成坏账。","tags":["finance","working"],"xpReward":10 },
  { "id":"bus_q071","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业已收到供应商货物、但尚未支付的货款，记为？","type":"choice","options":["应收账款","应付账款 Creditors（trade payables）","现金","存货"],"answer":"应付账款 Creditors（trade payables）","explain":"应付账款是企业欠供应商的钱，属流动负债，相当于免费的短期融资。","tags":["finance","working"],"xpReward":10 },
  { "id":"bus_q072","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业囤积过多原材料和成品库存，最直接的负面影响是？","type":"choice","options":["占用大量营运资本、增加仓储与减值风险","提高产品质量","降低固定成本","增加销售收入"],"answer":"占用大量营运资本、增加仓储与减值风险","explain":"库存压住现金，还可能过时、损坏；JIT 正是为了减少这种占用。","tags":["finance","working"],"xpReward":10 },
  { "id":"bus_q073","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"企业不直接购买设备，而是长期租用、按期付租金，这种方式是？","type":"choice","options":["租赁 Leasing","股权融资","留存利润","发行债券"],"answer":"租赁 Leasing","explain":"租赁避免一次性大额支出、可更新设备，但累计租金可能高于直接买价。","tags":["finance","sources"],"xpReward":10 },
  { "id":"bus_q074","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"下列哪一项最贴近「众筹（crowdfunding）」的含义？","type":"choice","options":["向银行一次性申请大额抵押贷款","通过互联网向大量普通投资者或客户募集小额资金","把利润全部留存","出售厂房换取现金"],"answer":"通过互联网向大量普通投资者或客户募集小额资金","explain":"众筹借助网络从众多小额支持者处募资，适合创意产品和初创企业。","tags":["finance","sources"],"xpReward":10 },
  { "id":"bus_q075","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"解释固定成本与变动成本的区别，并各举一例。","type":"essay","options":[],"answer":"固定成本是短期内不随产量变化的成本，如厂房租金、固定工资，即使停产也要支付；变动成本随产量成正比变化，如每件产品的原材料、计件工资。总成本＝固定成本＋变动成本。","explain":"评分要点：①固定成本定义＋举例（租金/固定工资/折旧）；②变动成本定义＋举例（原材料/计件工资/包装）；③说明停产时固定成本仍发生、变动成本归零。","tags":["finance","costs"],"xpReward":5 },
  { "id":"bus_q076","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"一家公司账面利润不错，却因扩张太快、现金被存货和应收账款占满而发不出工资。请解释这种营运资本紧张现象。","type":"essay","options":[],"answer":"快速增长会大量采购存货、给客户赊销，现金先流出而收入尚未到账。利润虽增加，但营运资本被存货和应收账款占死，出现「有利润、没现金」。企业需匹配增长节奏、加快收款、控制库存。","explain":"评分要点：①利润与现金流不同；②扩张导致存货与应收账款占用现金；③现金流出早于收入到账；④对策：控制增长速度、催收、压缩库存。","tags":["finance","working"],"xpReward":5 },
  { "id":"bus_q077","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"对比股权融资（发行股票）与债务融资（银行贷款）的主要优缺点。","type":"essay","options":[],"answer":"股权融资：无需还本、不增加固定利息负担、风险低；但稀释控制权、需分红、发行成本高。债务融资：不稀释控制权、利息可抵税；但必须按期还本付息，经营差时压力大、可能违约。","explain":"评分要点：①股权优点（不还本/风险低）与缺点（稀释/分红/成本高）；②债务优点（保控制权/抵税）与缺点（还本付息/违约风险）。能对比分析给满分。","tags":["finance","sources"],"xpReward":5 },
  { "id":"bus_q078","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"解释盈亏平衡分析对企业决策有什么用处，又有哪些局限。","type":"essay","options":[],"answer":"用处：知道至少要卖多少才不亏、测算价格或成本变化对利润的影响、评估是否值得上新项目、计算安全边际。局限：假设成本和价格恒定、产销完全一致，现实中并不成立；且只看数量、不考虑市场需求。","explain":"评分要点：①用处（求BEP/定价决策/安全边际/项目评估）；②局限（假设线性、忽略价格竞争与需求、静态）。","tags":["finance","bep"],"xpReward":5 },
  { "id":"bus_q079","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"解释营运资本对一家企业为什么重要，企业可从哪些方面改善营运资本管理？","type":"essay","options":[],"answer":"营运资本是日常运转的「现金血液」，不足会发不出工资、付不了货款而倒闭。改善：加快收回应收账款、控制和压缩库存、合理利用应付账款的账期、做好现金预算。","explain":"评分要点：①营运资本＝流动资产－流动负债及其作用；②现金流断裂风险；③改善手段（催收/控库存/利用账期/现金预算）。","tags":["finance","working"],"xpReward":5 },
  { "id":"bus_q080","exam_board":"CIE","subject":"business","chapter":"Finance","topicId":"bus_finance","question":"解释损益表中「毛利」与「净利润」的区别。","type":"essay","options":[],"answer":"毛利＝销售收入－直接销售成本（原材料、直接人工），反映产品本身的盈利空间。净利润＝毛利再扣除所有费用（租金、工资、营销、利息、税）后的最终利润，才是真正归企业和股东的钱。","explain":"评分要点：①毛利＝收入－直接成本；②净利润＝再减各项费用、利息、税；③说明毛利高不等于最终赚钱（费用过高也会亏损）。","tags":["finance","accounts"],"xpReward":5 },

  /* ============ 运营管理 Operations（bus_q081 ~ bus_q090，共10题） ============ */
  { "id":"bus_q081","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"为一位客户单独设计并建造一栋定制别墅，这种生产方式是？","type":"choice","options":["单件（订制）生产 Job production","批量生产","流水线生产","大量生产"],"answer":"单件（订制）生产 Job production","explain":"单件生产按客户独特要求做，如定制建筑、婚纱、桥梁，单件小批量、单位成本高。","tags":["operations","methods"],"xpReward":10 },
  { "id":"bus_q082","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"面包店每次烤出一批相同口味的面包，然后再换下一种口味，属于？","type":"choice","options":["单件生产","批量生产 Batch production","流水线生产","连续生产"],"answer":"批量生产 Batch production","explain":"批量生产成组、轮流生产不同规格，灵活但有换产成本，适合中种类、中产量。","tags":["operations","methods"],"xpReward":10 },
  { "id":"bus_q083","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"汽车装配线上产品经过固定工序、连续移动、标准化大量出产，属于？","type":"choice","options":["单件生产","批量生产","流水线（大量）生产 Flow/mass production","订制生产"],"answer":"流水线（大量）生产 Flow/mass production","explain":"流水线/大量生产标准化、连续、产量大、单位成本低，但产品灵活性差。","tags":["operations","methods"],"xpReward":10 },
  { "id":"bus_q084","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"生产率（productivity）的常用计算公式是？","type":"choice","options":["产出÷投入","投入÷产出","产出＋投入","固定成本÷产量"],"answer":"产出÷投入","explain":"生产率＝产出÷投入（如人均产量、单位工时产出），衡量资源利用效率。","tags":["operations","productivity"],"xpReward":10 },
  { "id":"bus_q085","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"在生产完成后对成品进行检验、挑出次品，这种做法属于？","type":"choice","options":["质量保证 QA","质量控制 QC（事后检验）","准时制 JIT","规模经济"],"answer":"质量控制 QC（事后检验）","explain":"QC侧重事后检验把关；QA侧重在流程中预防缺陷、全过程保证质量。","tags":["operations","quality"],"xpReward":10 },
  { "id":"bus_q086","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"强调在设计和生产流程各环节预防缺陷、而不是只靠最后检验，这属于？","type":"choice","options":["质量保证 QA","事后检验 QC","库存堆积","批量换产"],"answer":"质量保证 QA","explain":"QA是系统性预防，目标是第一次就做对；QC是事后挑次品。","tags":["operations","quality"],"xpReward":10 },
  { "id":"bus_q087","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"准时制（JIT）生产的主要风险是？","type":"choice","options":["库存太多占用资金","一旦供应链中断就可能停工待料","产品质量必然下降","员工无法培训"],"answer":"一旦供应链中断就可能停工待料","explain":"JIT几乎零库存、靠供应商及时供货；供应链一断（如天气、疫情）就停产。","tags":["operations","jit"],"xpReward":10 },
  { "id":"bus_q088","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"企业生产规模扩大后，单位平均成本下降，这一现象称为？","type":"choice","options":["规模经济 Economies of scale","边际收益递减","折旧","安全边际"],"answer":"规模经济 Economies of scale","explain":"大批量采购、专业化分工、更好的设备使单位成本随产量上升而下降。","tags":["operations","scale"],"xpReward":10 },
  { "id":"bus_q089","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"对比批量生产（batch）与流水线/大量生产（flow/mass）的优缺点。","type":"essay","options":[],"answer":"批量生产：可小批量、多品种切换，灵活适应不同口味和规格，但换产有成本、单位成本中等。流水线/大量生产：标准化、连续、产量大、单位成本低、质量稳定，但产品缺乏灵活性、转产难、初始投资大。","explain":"评分要点：①批量生产优（灵活/多品种）与劣（换产成本/效率受限）；②流水线优（低成本/高效率/稳定）与劣（不灵活/投资大）。能结合例子给满分。","tags":["operations","methods"],"xpReward":5 },
  { "id":"bus_q090","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"解释企业为什么采用精益生产与准时制（JIT），以及它有什么主要风险。","type":"essay","options":[],"answer":"精益/JIT通过只在需要时生产和进货，大幅减少库存、仓储和资金占用，暴露流程问题、提高效率和质量。风险是几乎没有缓冲库存，一旦供应商延迟、机器故障或需求突变，就可能停工，因此要求供应链非常可靠。","explain":"评分要点：①目的（减库存/占资金/提效提质）；②机制（按需生产、拉式系统）；③风险（供应链中断即停工、要求供应商稳定）。","tags":["operations","jit"],"xpReward":5 },

  /* ============ 人力资源管理 HR（bus_q091 ~ bus_q100，共10题） ============ */
  { "id":"bus_q091","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"企业从内部提拔或调岗招聘员工，最主要的优点是？","type":"choice","options":["一定带来全新的外部思路","成本较低、员工熟悉公司、有激励作用","可以省去所有培训","能无限扩大员工队伍"],"answer":"成本较低、员工熟悉公司、有激励作用","explain":"内部招聘省时省钱、激励士气；缺点是缺乏新鲜血液、可能造成内部竞争。","tags":["hr","recruitment"],"xpReward":10 },
  { "id":"bus_q092","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"外部招聘（广告、猎头）相比内部招聘的主要优点是？","type":"choice","options":["无需花费招聘费用","能带来外部新经验和新思路","员工无需适应","一定更便宜"],"answer":"能带来外部新经验和新思路","explain":"外部招聘引入新视角与技能，但成本高、新人需要适应、有文化磨合风险。","tags":["hr","recruitment"],"xpReward":10 },
  { "id":"bus_q093","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"新员工在岗位上由师傅边干边教、不离开工作现场，这种培训是？","type":"choice","options":["脱产培训 Off-the-job","在职培训 On-the-job training","远程教育","脱产学习"],"answer":"在职培训 On-the-job training","explain":"OJT边做边学、成本低、马上能用；脱产培训是离开岗位去课堂或学校。","tags":["hr","training"],"xpReward":10 },
  { "id":"bus_q094","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"员工暂时离开工作岗位，到学校或专门课程学习，属于？","type":"choice","options":["在职培训","脱产培训 Off-the-job training","师徒制","轮岗"],"answer":"脱产培训 Off-the-job training","explain":"脱产培训可系统学习、专注，但占用工时、成本较高。","tags":["hr","training"],"xpReward":10 },
  { "id":"bus_q095","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"销售人员按销售额的一定比例获得报酬，这种金钱激励是？","type":"choice","options":["计时工资","佣金 Commission","年终奖","岗位津贴"],"answer":"佣金 Commission","explain":"佣金随业绩浮动，激励销售但可能造成短期行为；计时工资则固定稳定。","tags":["hr","motivation"],"xpReward":10 },
  { "id":"bus_q096","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"下列哪一项属于非金钱激励（non-financial motivation）？","type":"choice","options":["按件计酬","让员工承担更有意义、更完整的工作（工作丰富化）","销售提成","加班费"],"answer":"让员工承担更有意义、更完整的工作（工作丰富化）","explain":"认可、晋升、工作丰富化、良好工作环境都是非金钱激励；赫茨伯格强调这类因素带来真正满意。","tags":["hr","motivation"],"xpReward":10 },
  { "id":"bus_q097","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"在马斯洛需求层次中，最高层、指发挥个人潜能的需求是？","type":"choice","options":["生理需求","安全需求","自我实现 Self-actualization","社交需求"],"answer":"自我实现 Self-actualization","explain":"马斯洛从生理、安全、社交、尊重到自我实现，低层满足后才追求高层。","tags":["hr","motivation"],"xpReward":10 },
  { "id":"bus_q098","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"一家企业管理层级少、管理幅度宽、上下级沟通路径短，属于？","type":"choice","options":["层级式（高耸）结构","扁平式结构 Flat structure","矩阵结构","事业部结构"],"answer":"扁平式结构 Flat structure","explain":"扁平结构层级少、授权多、沟通快；高耸（层级式）结构层级多、控制严但沟通慢。","tags":["hr","structure"],"xpReward":10 },
  { "id":"bus_q099","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"对比内部招聘与外部招聘的优缺点。","type":"essay","options":[],"answer":"内部招聘：优点是成本低、员工熟悉公司、有激励作用、上岗快；缺点是缺乏新鲜思路、易形成内部派系、可选范围小。外部招聘：优点是带来新经验新思路、可选范围广；缺点是成本高、适应期长、可能选错人。","explain":"评分要点：①内部优（省钱/熟悉/激励）与劣（缺新鲜血液/范围小）；②外部优（新思路/范围广）与劣（贵/适应风险）。","tags":["hr","recruitment"],"xpReward":5 },
  { "id":"bus_q100","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"解释企业为什么要激励员工，并分别举出一种金钱和一种非金钱激励手段。","type":"essay","options":[],"answer":"激励能提高士气、生产率和留任率、降低离职。金钱手段如计件工资、佣金、奖金；非金钱手段如晋升、公开认可、工作丰富化、改善工作环境。不同人需求不同，应组合使用。","explain":"评分要点：①激励目的（士气/生产率/留人）；②金钱手段一例（工资/奖金/佣金）；③非金钱手段一例（认可/晋升/工作丰富化）。","tags":["hr","motivation"],"xpReward":5 },

  /* ============ 增长战略 Growth（bus_q101 ~ bus_q110，共10题） ============ */
  { "id":"bus_q101","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"企业靠自身增加产能、开新店、拓展市场来慢慢做大，属于？","type":"choice","options":["内部（有机）增长 Internal/organic growth","合并收购","特许经营","清算"],"answer":"内部（有机）增长 Internal/organic growth","explain":"有机增长靠自身积累，慢但风险小、文化统一；外部增长靠并购，快但整合难。","tags":["growth","organic"],"xpReward":10 },
  { "id":"bus_q102","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"两家地位相当的公司自愿合并为一家新公司，称为？","type":"choice","options":["收购 Acquisition","合并 Merger","合资","外包"],"answer":"合并 Merger","explain":"合并是双方平等结合；收购是一方买下另一方（可能非自愿）。","tags":["growth","external"],"xpReward":10 },
  { "id":"bus_q103","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"两家同行业、同环节的啤酒公司合并，属于哪种一体化？","type":"choice","options":["横向一体化 Horizontal integration","后向纵向一体化","前向纵向一体化","混合一体化"],"answer":"横向一体化 Horizontal integration","explain":"横向＝收购同行（竞品），减少竞争、扩大份额；纵向是收购上下游。","tags":["growth","integration"],"xpReward":10 },
  { "id":"bus_q104","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"一家服装品牌收购了它的布料供应商，属于？","type":"choice","options":["横向一体化","后向纵向一体化（收购上游供应商）","前向纵向一体化","多元化"],"answer":"后向纵向一体化（收购上游供应商）","explain":"后向＝收购上游（供应商）；前向＝收购下游（分销商/零售），都属于纵向一体化。","tags":["growth","integration"],"xpReward":10 },
  { "id":"bus_q105","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"一家饮料公司收购了一家连锁酒店和一家游戏公司，业务毫无关联，属于？","type":"choice","options":["横向一体化","纵向一体化","混合（多元化）一体化 Conglomerate","特许经营"],"answer":"混合（多元化）一体化 Conglomerate","explain":"混合一体化进入不相关业务，目的是分散风险，但管理复杂、缺乏协同。","tags":["growth","integration"],"xpReward":10 },
  { "id":"bus_q106","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"特许经营（franchise）中，被特许人（加盟商）主要获得什么？","type":"choice","options":["免费永久使用品牌但不交任何费用","使用成熟品牌、产品和经营模式，并按约定交加盟费或分成","可以完全自定品牌","只负责生产不负责销售"],"answer":"使用成熟品牌、产品和经营模式，并按约定交加盟费或分成","explain":"特许经营让总部低成本扩张、加盟商借成熟模式创业；加盟商需遵守规定并付费。","tags":["growth","international"],"xpReward":10 },
  { "id":"bus_q107","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"两家公司各出资、共同成立一个新公司来合作做项目，称为？","type":"choice","options":["合资 Joint venture","收购","外包","清算"],"answer":"合资 Joint venture","explain":"合资共担风险、共享资源，常用于进入外国或陌生市场。","tags":["growth","international"],"xpReward":10 },
  { "id":"bus_q108","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"企业把非核心的生产或客服环节交给外部第三方去做，主要动机是？","type":"choice","options":["提高自己的管理复杂度","降低成本、聚焦核心业务","增加固定资产","完全控制质量"],"answer":"降低成本、聚焦核心业务","explain":"外包/外迁可降本、利用专业方，但可能失去控制、影响质量与本地就业。","tags":["growth","international"],"xpReward":10 },
  { "id":"bus_q109","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"对比内部（有机）增长与外部增长（合并/收购）的优缺点。","type":"essay","options":[],"answer":"内部增长：优点是风险小、文化统一、节奏可控；缺点是速度慢、可能错失机会。外部增长：优点是快速扩大规模和市场份额、获得所需能力；缺点是成本高、整合困难、文化冲突、负债压力大。","explain":"评分要点：①内部优（稳/可控）与劣（慢）；②外部优（快/获能力份额）与劣（贵/整合难/文化冲突）。","tags":["growth","external"],"xpReward":5 },
  { "id":"bus_q110","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"企业走向国际化有哪些常见方式？又面临哪些主要风险？","type":"essay","options":[],"answer":"常见方式：出口、外包/外迁、特许经营、合资、直接投资设厂。风险：汇率波动、文化与法规差异、政治不稳定、运输与供应链复杂、管理难度大增。","explain":"评分要点：①国际化方式（出口/外包/特许/合资/直接投资）任举两三种；②风险（汇率/文化法规/政治/供应链/管理）任举两三点。","tags":["growth","international"],"xpReward":5 },

  /* ============ 商业活动与企业组织 Understanding（bus_q111 ~ bus_q139，共29题） ============ */
  { "id":"bus_q111","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"企业存在的根本目的最准确的是？","type":"choice","options":["单纯为了让老板赚钱","识别并满足顾客需要、创造利润以应对资源稀缺","生产尽可能多的产品","消灭所有竞争对手"],"answer":"识别并满足顾客需要、创造利润以应对资源稀缺","explain":"企业因资源稀缺而存在，核心是有效满足顾客需要并获利，而不是单纯逐利或求大。","tags":["understanding","purpose"],"xpReward":10 },
  { "id":"bus_q112","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"经济学中「稀缺性」（scarcity）指的是？","type":"choice","options":["商品完全卖光","资源有限而人的欲望无限，必须做出选择","企业没有库存","消费者没有收入"],"answer":"资源有限而人的欲望无限，必须做出选择","explain":"稀缺是资源相对欲望不足，企业和社会都要据此决定生产什么、如何分配。","tags":["understanding","scarcity"],"xpReward":10 },
  { "id":"bus_q113","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"生产的四大要素（生产资源）不包括下列哪一项？","type":"choice","options":["土地","劳动","资本","广告"],"answer":"广告","explain":"生产要素是土地、劳动、资本和企业才能；广告是营销活动，不是生产要素。","tags":["understanding","factors"],"xpReward":10 },
  { "id":"bus_q114","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"农民种植小麦属于哪个产业部门？","type":"choice","options":["第一产业 Primary sector","第二产业 Secondary sector","第三产业 Tertiary sector","第四产业"],"answer":"第一产业 Primary sector","explain":"农业、采矿、林业、渔业等直接取自自然资源的活动属第一产业。","tags":["understanding","sectors"],"xpReward":10 },
  { "id":"bus_q115","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"汽车工厂把钢材加工成汽车，属于？","type":"choice","options":["第一产业","第二产业 Secondary sector（制造业）","第三产业","采掘业"],"answer":"第二产业 Secondary sector（制造业）","explain":"制造业、建筑业把原料加工成产品，属第二产业。","tags":["understanding","sectors"],"xpReward":10 },
  { "id":"bus_q116","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"银行、学校、理发店提供服务，属于？","type":"choice","options":["第一产业","第二产业","第三产业 Tertiary sector","农业"],"answer":"第三产业 Tertiary sector","explain":"各类服务业（金融、教育、零售、餐饮）都属第三产业。","tags":["understanding","sectors"],"xpReward":10 },
  { "id":"bus_q117","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"一个人独立出资、自己经营、对企业债务承担无限责任，这种组织形式是？","type":"choice","options":["个体企业 Sole trader","有限公司","合伙企业","上市公司"],"answer":"个体企业 Sole trader","explain":"个体企业由一人拥有经营，设立简单、利润独享，但个人要承担无限责任。","tags":["understanding","organisation"],"xpReward":10 },
  { "id":"bus_q118","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"个体企业（sole trader）最主要的优点是？","type":"choice","options":["责任有限、风险小","决策自由、利润独享、设立简单","必须公开财报","融资很容易"],"answer":"决策自由、利润独享、设立简单","explain":"个体户自己说了算、税后利润全归自己，缺点是无限责任和融资难。","tags":["understanding","organisation"],"xpReward":10 },
  { "id":"bus_q119","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"个体企业最主要的缺点是？","type":"choice","options":["决策太慢","无限责任，个人资产可能被用来抵债","必须缴纳公司税","不能自己定价"],"answer":"无限责任，个人资产可能被用来抵债","explain":"无限责任意味着企业欠债时业主个人房产、存款都可能被追偿。","tags":["understanding","organisation"],"xpReward":10 },
  { "id":"bus_q120","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"两个或以上的人共同出资、共担风险、共享利润，这种组织形式是？","type":"choice","options":["合伙企业 Partnership","个体企业","有限公司","特许经营"],"answer":"合伙企业 Partnership","explain":"合伙汇集更多资金和技能，但普通合伙人同样承担无限责任。","tags":["understanding","organisation"],"xpReward":10 },
  { "id":"bus_q121","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"有限公司（limited company）最核心的法律特征是？","type":"choice","options":["股东对企业债务承担无限责任","企业是独立法人，股东以出资额为限承担有限责任","不需要记账","不能发行股票"],"answer":"企业是独立法人，股东以出资额为限承担有限责任","explain":"有限公司是独立法人，股东最多亏掉投入的钱，个人资产受保护。","tags":["understanding","organisation"],"xpReward":10 },
  { "id":"bus_q122","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"下列哪一项是有限公司相比个体企业的主要优势？","type":"choice","options":["设立更简单","有限责任、更容易通过发行股票融资","完全不受监管","不需要报税"],"answer":"有限责任、更容易通过发行股票融资","explain":"有限责任保护个人资产，公司还能向投资者发行股权融资。","tags":["understanding","organisation"],"xpReward":10 },
  { "id":"bus_q123","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"许多新企业成立初期最首要的目标通常是？","type":"choice","options":["利润最大化","生存 Survival","市场份额第一","企业社会责任"],"answer":"生存 Survival","explain":"新企业现金流脆弱，先活下来、稳住顾客和现金才是第一目标。","tags":["understanding","objectives"],"xpReward":10 },
  { "id":"bus_q124","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"下列哪一项最像企业的「非财务目标」？","type":"choice","options":["提高净利润","增加销售收入","减少对环境的影响、提升员工福祉","提高股东分红"],"answer":"减少对环境的影响、提升员工福祉","explain":"财务目标看利润、收入、分红；环保、员工福祉、社会责任属非财务目标。","tags":["understanding","objectives"],"xpReward":10 },
  { "id":"bus_q125","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"受企业决策影响、或能够影响企业的个人与群体（如员工、顾客、供应商、政府），称为？","type":"choice","options":["竞争对手","利益相关者 Stakeholders","股东 only","批发商"],"answer":"利益相关者 Stakeholders","explain":"利益相关者包括内部（员工、股东）和外部（顾客、供应商、政府、社区）等多方。","tags":["understanding","stakeholders"],"xpReward":10 },
  { "id":"bus_q126","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"下列哪一组最能说明利益相关者之间的目标冲突？","type":"choice","options":["员工想涨薪、股东想压低成本多分红","顾客想要低价、顾客也想要低价","两个供应商都想供货","政府想多收税、政府也想多收税"],"answer":"员工想涨薪、股东想压低成本多分红","explain":"员工追求高工资，股东追求低成本高回报，二者常直接冲突。","tags":["understanding","stakeholders"],"xpReward":10 },
  { "id":"bus_q127","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"股东（owners）最核心的利益通常是？","type":"choice","options":["稳定就业与高工资","投资回报与企业资产增值","低价商品","减少污染"],"answer":"投资回报与企业资产增值","explain":"股东出资是为了分红和股价/资产增值；高工资是员工关心的。","tags":["understanding","stakeholders"],"xpReward":10 },
  { "id":"bus_q128","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"员工作为利益相关者最关心的通常是？","type":"choice","options":["股价上涨","工资、工作条件与职业发展","低物价","税收"],"answer":"工资、工作条件与职业发展","explain":"员工关注薪酬、安全环境、晋升机会和工作稳定性。","tags":["understanding","stakeholders"],"xpReward":10 },
  { "id":"bus_q129","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"顾客作为利益相关者最关心的通常是？","type":"choice","options":["企业分红","商品质量与价格是否合理、售后保障","政府税收","员工招聘"],"answer":"商品质量与价格是否合理、售后保障","explain":"顾客要物有所值、质量可靠和良好售后。","tags":["understanding","stakeholders"],"xpReward":10 },
  { "id":"bus_q130","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"「企业社会责任」（CSR）指的是？","type":"choice","options":["企业只对股东利润负责","企业在追求利润同时兼顾对社会、环境和利益相关者的责任","政府强制企业捐款","企业不用承担任何责任"],"answer":"企业在追求利润同时兼顾对社会、环境和利益相关者的责任","explain":"CSR要求企业超越单纯盈利，主动考虑对社会和环境的影响。","tags":["understanding","csr"],"xpReward":10 },
  { "id":"bus_q131","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"善于发现商机、整合资源、承担风险创办新企业的人，称为？","type":"choice","options":["雇员","企业家 Entrepreneur","股东 only","银行家"],"answer":"企业家 Entrepreneur","explain":"企业家发现机会、组织生产要素、承担经营风险以获取利润。","tags":["understanding","enterprise"],"xpReward":10 },
  { "id":"bus_q132","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"企业家承担经营风险，主要回报是？","type":"choice","options":["固定工资","利润与企业成长带来的回报","政府补贴","银行利息"],"answer":"利润与企业成长带来的回报","explain":"企业家不像雇员拿固定工资，其回报来自利润和企业增值，但也要承担亏损风险。","tags":["understanding","enterprise"],"xpReward":10 },
  { "id":"bus_q133","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"当一个经济体从以制造业为主转向以服务业为主，这种趋势称为？","type":"choice","options":["去中心化","产业结构转型（去工业化/服务化）","规模经济","纵向一体化"],"answer":"产业结构转型（去工业化/服务化）","explain":"发达经济体第三产业比重上升、制造业比重下降，是产业结构转型。","tags":["understanding","sectors"],"xpReward":10 },
  { "id":"bus_q134","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"政府对企业利润征收的税称为？","type":"choice","options":["增值税","企业所得税 Corporation tax","关税","消费税"],"answer":"企业所得税 Corporation tax","explain":"企业所得税按利润征收，直接减少企业可留存的资金。","tags":["understanding","tax"],"xpReward":10 },
  { "id":"bus_q135","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"对比个体企业与有限公司在责任和融资上的主要区别。","type":"essay","options":[],"answer":"个体企业：业主承担无限责任，个人资产可被用来抵债；资金主要靠自有储蓄和利润，融资渠道有限。有限公司：是独立法人，股东承担有限责任，个人资产受保护；可通过发行股票、向银行贷款等方式更容易募集较大资金，但要公开财报、受监管。","explain":"评分要点：①个体户无限责任、有限公司有限责任；②个体户融资靠自有资金、有限公司可发行股权；③有限公司监管更严。答出任两点给分。","tags":["understanding","organisation"],"xpReward":5 },
  { "id":"bus_q136","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"下列哪一种企业最可能享有「有限责任」？","type":"choice","options":["街角个体户","两人律师合伙事务所","注册成立的私人有限公司","自由职业设计师"],"answer":"注册成立的私人有限公司","explain":"只有注册为有限公司的企业才享有有限责任；个体户和普通合伙人通常承担无限责任。","tags":["understanding","organisation"],"xpReward":10 },
  { "id":"bus_q137","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"企业把「市场份额增长」作为目标，通常意味着它更看重？","type":"choice","options":["短期利润最大化","扩大销量和顾客基数、压过竞争对手","立即分红","减少投资"],"answer":"扩大销量和顾客基数、压过竞争对手","explain":"追求市场份额往往意味着先牺牲短期利润换规模和长期地位。","tags":["understanding","objectives"],"xpReward":10 },
  { "id":"bus_q138","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"供应商作为利益相关者，最关心的是？","type":"choice","options":["企业能否按时付款、持续下订单","产品安全","员工假期","政府政策"],"answer":"企业能否按时付款、持续下订单","explain":"供应商要稳定的订单和按时回款，这直接关系到他们的收入和现金流。","tags":["understanding","stakeholders"],"xpReward":10 },
  { "id":"bus_q139","exam_board":"CIE","subject":"business","chapter":"Understanding","topicId":"bus_understanding","question":"下列哪一项属于企业的「长期/战略目标」而非短期目标？","type":"choice","options":["本周多卖 100 件","三年内成为本行业领先品牌、拓展海外市场","今天发工资","本月交电费"],"answer":"三年内成为本行业领先品牌、拓展海外市场","explain":"长期目标涉及多年战略方向；本周销量、本月电费是短期运营事项。","tags":["understanding","objectives"],"xpReward":10 },

  /* ============ 外部影响与全球化 External（bus_q140 ~ bus_q162，共23题） ============ */
  { "id":"bus_q140","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"政府对进口商品征收关税（tariff），对本地企业最可能的影响是？","type":"choice","options":["进口商品变贵、本地同类产品竞争压力减小","进口商品变便宜","本地企业必然倒闭","政府税收减少"],"answer":"进口商品变贵、本地同类产品竞争压力减小","explain":"关税抬高进口品价格，等于给本地产品一点价格保护，但也可能引发对方报复。","tags":["external","trade"],"xpReward":10 },
  { "id":"bus_q141","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"政府为鼓励某类产品生产而向企业发放补贴（subsidy），通常会？","type":"choice","options":["抬高企业成本","降低企业成本、刺激生产和投资","强制企业减产","增加消费者负担"],"answer":"降低企业成本、刺激生产和投资","explain":"补贴相当于政府帮企业分担成本，鼓励其扩大生产或采用新技术。","tags":["external","policy"],"xpReward":10 },
  { "id":"bus_q142","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"中央银行提高利率，对借款扩张的企业意味着？","type":"choice","options":["还贷利息成本下降","借贷成本上升、投资意愿下降","现金流入增加","不受任何影响"],"answer":"借贷成本上升、投资意愿下降","explain":"加息使贷款利息变贵，企业借钱扩张更谨慎，消费和投资都会受抑。","tags":["external","policy"],"xpReward":10 },
  { "id":"bus_q143","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"下列哪一项属于政府的「法规监管」对企业的约束？","type":"choice","options":["提高工资","环保法要求企业控制排污、劳动法规定最低工资","增加广告","降低价格"],"answer":"环保法要求企业控制排污、劳动法规定最低工资","explain":"法规强制企业达到环保、用工、安全等标准，违规会被罚款或停业。","tags":["external","policy"],"xpReward":10 },
  { "id":"bus_q144","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"企业为减少污染、使用可持续材料而增加成本，但可能换来的好处是？","type":"choice","options":["短期利润一定上升","品牌形象提升、赢得环保顾客、规避未来罚款","完全没有好处","政府立刻补贴"],"answer":"品牌形象提升、赢得环保顾客、规避未来罚款","explain":"环保投入短期增成本，但能改善声誉、吸引顾客并降低合规风险。","tags":["external","environment"],"xpReward":10 },
  { "id":"bus_q145","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"一国货币对外升值，对出口企业的影响是？","type":"choice","options":["本国商品在海外变贵、出口竞争力下降","本国商品变便宜","出口一定增加","没有影响"],"answer":"本国商品在海外变贵、出口竞争力下降","explain":"本币升值后外国顾客要用更多外币换汇，本国货变贵，出口受压。","tags":["external","exchange"],"xpReward":10 },
  { "id":"bus_q146","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"汇率波动对跨国经营企业的主要风险是？","type":"choice","options":["工资必然上涨","换汇时收入或成本的本币价值不确定","顾客消失","政府禁止贸易"],"answer":"换汇时收入或成本的本币价值不确定","explain":"汇率起伏会使同样一笔外币收入折算成本币时变多变少，形成汇兑风险。","tags":["external","exchange"],"xpReward":10 },
  { "id":"bus_q147","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"两国之间取消关税、降低贸易壁垒，这属于？","type":"choice","options":["贸易保护","自由贸易 Free trade 趋势","自给自足","国有化"],"answer":"自由贸易 Free trade 趋势","explain":"降低关税和壁垒让商品跨国自由流动，是自由贸易方向。","tags":["external","trade"],"xpReward":10 },
  { "id":"bus_q148","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"企业把客服或生产环节搬到劳动力更便宜的国家，称为？","type":"choice","options":["外包/外迁 Outsourcing/offshoring","特许经营","合并","清算"],"answer":"外包/外迁 Outsourcing/offshoring","explain":"把非核心或低成本环节交给外部/海外做，目的是降本、聚焦核心业务。","tags":["external","globalization"],"xpReward":10 },
  { "id":"bus_q149","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"外包可能给企业带来的主要风险是？","type":"choice","options":["成本必然上升","对质量和交货的控制减弱、可能影响品牌","员工一定增加","完全消除风险"],"answer":"对质量和交货的控制减弱、可能影响品牌","explain":"远程管理外包方难以及时把控质量，一旦出问题会损害品牌口碑。","tags":["external","globalization"],"xpReward":10 },
  { "id":"bus_q150","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"两家同行业、同环节的企业合并（如两家航空公司合并），属于？","type":"choice","options":["横向一体化 Horizontal integration","后向纵向一体化","前向纵向一体化","混合多元化"],"answer":"横向一体化 Horizontal integration","explain":"收购或合并同行（竞争对手）以减少竞争、扩大市场份额。","tags":["external","integration"],"xpReward":10 },
  { "id":"bus_q151","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"一家汽车厂收购了它的轮胎供应商，属于？","type":"choice","options":["横向一体化","后向纵向一体化 Backward vertical integration","前向纵向一体化","混合一体化"],"answer":"后向纵向一体化 Backward vertical integration","explain":"收购上游供应商（供应链的后方）以控制原料和供货。","tags":["external","integration"],"xpReward":10 },
  { "id":"bus_q152","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"一家服装制造商收购了连锁零售门店，属于？","type":"choice","options":["横向一体化","后向纵向一体化","前向纵向一体化 Forward vertical integration","多元化"],"answer":"前向纵向一体化 Forward vertical integration","explain":"收购下游分销/零售环节（靠近顾客的前方）以控制销售渠道。","tags":["external","integration"],"xpReward":10 },
  { "id":"bus_q153","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"企业进入与原有业务完全无关的行业以分散风险，属于？","type":"choice","options":["横向一体化","纵向一体化","混合（多元化）一体化 Conglomerate","特许经营"],"answer":"混合（多元化）一体化 Conglomerate","explain":"多元化进入不相关业务以分散风险，但管理复杂、缺乏协同。","tags":["external","integration"],"xpReward":10 },
  { "id":"bus_q154","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"横向一体化（收购同行）最主要的动机是？","type":"choice","options":["控制原材料","减少竞争、扩大市场份额","直接接触顾客","分散到无关行业"],"answer":"减少竞争、扩大市场份额","explain":"合并竞争对手可削弱价格战、提高市场集中度和议价能力。","tags":["external","integration"],"xpReward":10 },
  { "id":"bus_q155","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"跨国企业在海外直接投资建厂（FDI）相比出口的好处是？","type":"choice","options":["完全没有风险","更贴近市场、避开关税、利用当地要素","不需要管理","汇率风险消失"],"answer":"更贴近市场、避开关税、利用当地要素","explain":"直接投资可绕开关税、靠近顾客、利用当地低成本劳动力和资源，但管理更复杂。","tags":["external","globalization"],"xpReward":10 },
  { "id":"bus_q156","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"全球化对发展中国家本地小企业的主要挑战是？","type":"choice","options":["完全没有竞争","要与进入本地的跨国大公司竞争","顾客变少","政府禁止经营"],"answer":"要与进入本地的跨国大公司竞争","explain":"全球化打开市场，本地小企要面对资金、品牌都更强的跨国巨头。","tags":["external","globalization"],"xpReward":10 },
  { "id":"bus_q157","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"政府提高企业所得税，对企业最直接的影响是？","type":"choice","options":["税后利润减少、可再投资资金变少","收入必然增加","成本结构不变","股价一定上涨"],"answer":"税后利润减少、可再投资资金变少","explain":"税率上升直接吃掉利润，企业能留存再投资的钱相应减少。","tags":["external","policy"],"xpReward":10 },
  { "id":"bus_q158","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"分析政府加税与发放补贴分别会如何影响一家制造企业的决策。","type":"essay","options":[],"answer":"加税（如提高企业所得税或增值税）会抬高成本、减少税后利润，企业可能削减投资、涨价或控制扩张。发放补贴则降低企业成本、增加现金流，会鼓励企业扩大生产、更新设备或进入被扶持的产业。企业会据此调整产能扩张、定价和投资方向。","explain":"评分要点：①加税抬高成本/减少利润、抑制投资；②补贴降低成本、鼓励生产投资；③能结合企业调整产能或定价决策更佳。","tags":["external","policy"],"xpReward":5 },
  { "id":"bus_q159","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"下列哪一项最能说明企业「受技术进步这一外部因素影响」？","type":"choice","options":["员工涨工资","电商兴起让实体店客流下降","银行加息","原材料涨价"],"answer":"电商兴起让实体店客流下降","explain":"新技术（电商、移动支付）改变顾客习惯，是企业难以控制的外部冲击。","tags":["external","technology"],"xpReward":10 },
  { "id":"bus_q160","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"企业采用更环保、可持续的做法，短期最可能？","type":"choice","options":["成本上升","收入立即翻倍","固定成本降为零","无需任何投入"],"answer":"成本上升","explain":"环保材料和工艺短期内通常更贵，会增加成本，但长期可改善声誉和合规。","tags":["external","environment"],"xpReward":10 },
  { "id":"bus_q161","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"国际贸易中，一国对进口数量设上限，称为？","type":"choice","options":["关税","配额 Quota","补贴","制裁"],"answer":"配额 Quota","explain":"配额直接限制进口数量；关税是对进口品加税，两者都是贸易保护手段。","tags":["external","trade"],"xpReward":10 },
  { "id":"bus_q162","exam_board":"CIE","subject":"business","chapter":"External","topicId":"bus_external","question":"讨论企业走向全球化（如外包、海外设厂）带来的两点收益与两点风险。","type":"essay","options":[],"answer":"收益：①利用海外低成本劳动力和资源降低成本；②进入更大的海外市场、扩大销量和品牌影响。风险：①汇率波动和文化、法规差异增加经营不确定性；②供应链拉长、管理难度和政治风险上升。","explain":"评分要点：收益任举两点（降本/扩市场/避关税）；风险任举两点（汇率/文化法规/政治/供应链管理）。能对比分析给满分。","tags":["external","globalization"],"xpReward":5 },

  /* ============ 人力资源与员工激励 People（bus_q163 ~ bus_q182，共20题） ============ */
  { "id":"bus_q163","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"招聘前先明确岗位任务、所需技能与任职资格，这份文件称为？","type":"choice","options":["工资单","岗位说明书 Job description","财报","组织架构图"],"answer":"岗位说明书 Job description","explain":"岗位说明书写明职责、要求和汇报关系，是选拔和考核的依据。","tags":["people","recruitment"],"xpReward":10 },
  { "id":"bus_q164","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"企业通过晋升内部员工填补空缺，相比外部招聘的缺点是？","type":"choice","options":["成本高","缺乏外部新鲜思路、可能引发内部竞争","上岗慢","必须打广告"],"answer":"缺乏外部新鲜思路、可能引发内部竞争","explain":"内部招聘省钱、激励人，但封闭循环、缺少外部新经验，落选者也易不满。","tags":["people","recruitment"],"xpReward":10 },
  { "id":"bus_q165","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"新员工在老师傅指导下边工作边学习，属于？","type":"choice","options":["脱产培训","在职培训 On-the-job training","远程教育","模拟培训"],"answer":"在职培训 On-the-job training","explain":"OJT在真实岗位上边做边学，成本低、立即可用。","tags":["people","training"],"xpReward":10 },
  { "id":"bus_q166","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"企业送员工到学校参加为期数月的全日制课程，属于？","type":"choice","options":["在职培训","脱产培训 Off-the-job training","轮岗","师徒制"],"answer":"脱产培训 Off-the-job training","explain":"脱产培训离开岗位系统学习，更全面但占用工时、成本较高。","tags":["people","training"],"xpReward":10 },
  { "id":"bus_q167","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"按工人完成的合格产品件数支付工资，这种薪酬方式是？","type":"choice","options":["计时工资","计件工资 Piece rate","固定月薪","养老金"],"answer":"计件工资 Piece rate","explain":"计件工资多劳多得、激励产量，但可能牺牲质量、造成收入波动。","tags":["people","motivation"],"xpReward":10 },
  { "id":"bus_q168","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"下列哪一项属于「非金钱激励」？","type":"choice","options":["计件工资","让员工参与决策、授予更大责任","销售佣金","年终奖"],"answer":"让员工参与决策、授予更大责任","explain":"参与决策、授权、认可、晋升都不直接给钱，属非金钱激励。","tags":["people","motivation"],"xpReward":10 },
  { "id":"bus_q169","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"按马斯洛需求层次，员工对稳定工作、社保和安全环境的需求属于？","type":"choice","options":["生理需求","安全需求 Safety needs","自我实现","社交需求"],"answer":"安全需求 Safety needs","explain":"稳定收入、安全工作条件、社会保障满足的是安全需求。","tags":["people","motivation"],"xpReward":10 },
  { "id":"bus_q170","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"按马斯洛，员工归属团队、获得友谊的需求属于？","type":"choice","options":["生理需求","社交（归属）需求 Social needs","尊重需求","安全需求"],"answer":"社交（归属）需求 Social needs","explain":"归属感、同事友谊、被团队接纳属于社交需求。","tags":["people","motivation"],"xpReward":10 },
  { "id":"bus_q171","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"赫茨伯格理论中，工资、工作条件这类「保健因素」的作用是？","type":"choice","options":["带来强烈满意","若不足会引起不满，做好了也只是消除不满","与满意度无关","决定晋升"],"answer":"若不足会引起不满，做好了也只是消除不满","explain":"保健因素只能防不满，真正的满意要靠激励因素。","tags":["people","motivation"],"xpReward":10 },
  { "id":"bus_q172","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"赫茨伯格认为真正能带来工作满意的「激励因素」是？","type":"choice","options":["提高基本工资","成就、认可、责任与晋升","改善照明","增加假期"],"answer":"成就、认可、责任与晋升","explain":"成就感、被认可、责任感和晋升机会才是赫茨伯格的满意来源。","tags":["people","motivation"],"xpReward":10 },
  { "id":"bus_q173","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"管理幅度（span of control）指的是？","type":"choice","options":["企业的总人数","一位管理者直接管辖的下属人数","公司层级总数","年度预算"],"answer":"一位管理者直接管辖的下属人数","explain":"管理幅度是一位上级直接管多少人；幅度宽则组织扁平，幅度窄则高耸。","tags":["people","structure"],"xpReward":10 },
  { "id":"bus_q174","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"一家企业层级很多、每级管辖人数少，这种结构通常称为？","type":"choice","options":["扁平结构","高耸（层级式）结构 Tall structure","矩阵结构","网络结构"],"answer":"高耸（层级式）结构 Tall structure","explain":"高耸结构层级多、幅度窄，控制严密但沟通链长。","tags":["people","structure"],"xpReward":10 },
  { "id":"bus_q175","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"扁平组织（flat structure）最主要的优点是？","type":"choice","options":["控制极严","沟通路径短、授权多、反应快","层级多","决策必须层层上报"],"answer":"沟通路径短、授权多、反应快","explain":"扁平结构层级少，信息传递快、基层有更多自主权。","tags":["people","structure"],"xpReward":10 },
  { "id":"bus_q176","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"信息从一线员工向上级反映问题，属于哪种沟通方向？","type":"choice","options":["自上而下","自下而上","横向","非正式"],"answer":"自下而上","explain":"下级向上级汇报、提建议是自下而上的沟通。","tags":["people","communication"],"xpReward":10 },
  { "id":"bus_q177","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"两个平级部门之间为协作而互通信息，属于？","type":"choice","options":["自上而下","横向沟通","垂直命令","外部沟通"],"answer":"横向沟通","explain":"平级部门之间的信息往来是横向沟通，便于跨部门协作。","tags":["people","communication"],"xpReward":10 },
  { "id":"bus_q178","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"定期对员工工作表现进行评估并反馈，称为？","type":"choice","options":["招聘","绩效考核 Performance appraisal","培训","解雇"],"answer":"绩效考核 Performance appraisal","explain":"绩效考核衡量员工表现、用于奖惩、晋升和培训安排。","tags":["people","appraisal"],"xpReward":10 },
  { "id":"bus_q179","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"高离职率（员工频繁跳槽）给企业带来的直接问题是？","type":"choice","options":["招聘培训成本上升、知识与客户关系流失","生产率必然上升","工资下降","无需任何成本"],"answer":"招聘培训成本上升、知识与客户关系流失","explain":"频繁招人、培训新人要花钱，老员工走还带走经验和客户关系。","tags":["people","retention"],"xpReward":10 },
  { "id":"bus_q180","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"解释为什么「加薪」不一定能长期提高员工积极性，并给出一种替代的非金钱激励。","type":"essay","options":[],"answer":"按赫茨伯格的观点，工资属于保健因素：不加会不满，但加了也只能暂时消除不满，不能带来真正的长期满意。替代的非金钱激励可以是：让员工承担更完整、更有意义的工作（工作丰富化）、公开认可其成就、给予更大自主权或晋升机会。","explain":"评分要点：①加薪是保健因素、只能消除不满；②长期满意靠激励因素；③给出一种非金钱激励（认可/授权/工作丰富化/晋升）。","tags":["people","motivation"],"xpReward":5 },
  { "id":"bus_q181","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"企业让员工在不同岗位间轮换工作，主要好处是？","type":"choice","options":["减少工资","培养多技能员工、避免工作单调、便于调配","增加管理难度","降低质量"],"answer":"培养多技能员工、避免工作单调、便于调配","explain":"轮岗让员工掌握多种技能、减少重复劳动的枯燥，也便于人手调配。","tags":["people","training"],"xpReward":10 },
  { "id":"bus_q182","exam_board":"CIE","subject":"business","chapter":"People","topicId":"bus_people","question":"下列哪一种情况最可能导致沟通失效？","type":"choice","options":["信息清晰、渠道恰当","信息过载、上下级层级太多、语言含糊","双向反馈","使用多种渠道"],"answer":"信息过载、上下级层级太多、语言含糊","explain":"层级多、信息过载和表达含糊都会造成信息失真和误解。","tags":["people","communication"],"xpReward":10 },

  /* ============ 运营与生产管理 Operations（bus_q183 ~ bus_q200，共18题） ============ */
  { "id":"bus_q183","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"为每位客户单独设计定制婚纱，最适合采用哪种生产方式？","type":"choice","options":["单件（订制）生产 Job production","批量生产","流水线生产","连续生产"],"answer":"单件（订制）生产 Job production","explain":"每件产品都按客户独特要求单独制作，属单件/订制生产。","tags":["operations","methods"],"xpReward":10 },
  { "id":"bus_q184","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"流水线/大量生产最突出的优点是？","type":"choice","options":["产品完全个性化","标准化、产量大、单位成本低","换产灵活","初始投资小"],"answer":"标准化、产量大、单位成本低","explain":"流水线连续标准化出产，效率高、单位成本低，但产品不灵活。","tags":["operations","methods"],"xpReward":10 },
  { "id":"bus_q185","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"批量生产（batch）相比流水线生产的主要灵活性体现在？","type":"choice","options":["完全不能换品种","可小批量轮换生产不同规格","单位成本最低","不需要工人"],"answer":"可小批量轮换生产不同规格","explain":"批量生产成组轮流做不同口味/规格，能适应多变需求。","tags":["operations","methods"],"xpReward":10 },
  { "id":"bus_q186","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"生产率提高意味着？","type":"choice","options":["同样投入产出更多、或同样产出投入更少","产量下降","成本上升","员工减少"],"answer":"同样投入产出更多、或同样产出投入更少","explain":"生产率＝产出÷投入，提高意味着资源利用更有效率。","tags":["operations","productivity"],"xpReward":10 },
  { "id":"bus_q187","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"企业产量扩大后单位平均成本下降，称为？","type":"choice","options":["规模不经济","规模经济 Economies of scale","折旧","安全边际"],"answer":"规模经济 Economies of scale","explain":"大批量采购、专业化分工使单位成本随产量上升而下降。","tags":["operations","scale"],"xpReward":10 },
  { "id":"bus_q188","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"企业规模过大导致协调困难、管理成本上升，称为？","type":"choice","options":["规模经济","规模不经济 Diseconomies of scale","学习曲线","沉没成本"],"answer":"规模不经济 Diseconomies of scale","explain":"规模过大后沟通、协调和管理变难，单位成本反而上升。","tags":["operations","scale"],"xpReward":10 },
  { "id":"bus_q189","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"在流程中预防缺陷、而不是等成品再挑次品，属于？","type":"choice","options":["事后检验 QC","质量保证 QA","库存积压","批量换产"],"answer":"质量保证 QA","explain":"QA强调系统预防、第一次就做对；QC是事后检验把关。","tags":["operations","quality"],"xpReward":10 },
  { "id":"bus_q190","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"准时制（JIT）生产对供应商的最关键要求是？","type":"choice","options":["大量囤积库存","能按时、按质、按量稳定供货","距离越远越好","价格越高越好"],"answer":"能按时、按质、按量稳定供货","explain":"JIT几乎零库存，全靠供应商可靠地及时补货，一断料就停产。","tags":["operations","jit"],"xpReward":10 },
  { "id":"bus_q191","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"下列哪一项最适合作为工厂选址靠近原料产地的理由？","type":"choice","options":["原料笨重易腐、运输成本高","顾客集中在市中心","需要大量工程师","风景好"],"answer":"原料笨重易腐、运输成本高","explain":"原料笨重、易损耗时靠近产地可省运费，如糖厂靠近甘蔗田。","tags":["operations","location"],"xpReward":10 },
  { "id":"bus_q192","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"下列哪一项最适合把客服/办事处设在靠近目标顾客的大城市？","type":"choice","options":["原料运输","贴近市场、便于响应顾客","降低原材料成本","减少用电"],"answer":"贴近市场、便于响应顾客","explain":"靠近顾客能更快响应需求、改善服务，适合服务业和办事处选址。","tags":["operations","location"],"xpReward":10 },
  { "id":"bus_q193","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"企业保留少量安全库存以防供应延迟，主要是为了？","type":"choice","options":["占用资金","降低停工待料风险","提高仓储成本","让产品过时"],"answer":"降低停工待料风险","explain":"安全库存是缓冲，应对到货延迟或需求突增，避免停产。","tags":["operations","inventory"],"xpReward":10 },
  { "id":"bus_q194","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"机器设备逐年计提折旧，是因为？","type":"choice","options":["设备升值","固定资产随使用损耗、成本需分摊到各期","现金流出增加","税收要求停止使用"],"answer":"固定资产随使用损耗、成本需分摊到各期","explain":"设备价值随磨损下降，通过折旧把成本合理分摊到使用年限。","tags":["operations","costs"],"xpReward":10 },
  { "id":"bus_q195","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"某厂 10 个工人一天生产 500 件，人均日产出是？","type":"choice","options":["50 件","500 件","5000 件","10 件"],"answer":"50 件","explain":"人均产出＝总产出÷人数＝500÷10＝50 件/人。","tags":["operations","productivity"],"xpReward":10 },
  { "id":"bus_q196","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"全面质量管理（TQM）强调的核心是？","type":"choice","options":["只靠最后检验","全员参与、全过程追求零缺陷、持续改进","只培训质检部门","增加库存"],"answer":"全员参与、全过程追求零缺陷、持续改进","explain":"TQM要求从高层到一线人人对质量负责，持续改进而非事后挑错。","tags":["operations","quality"],"xpReward":10 },
  { "id":"bus_q197","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"对比单件（订制）生产与流水线（大量）生产在产品灵活性和单位成本上的差异。","type":"essay","options":[],"answer":"单件（订制）生产：按客户独特要求制作，产品高度灵活、可完全定制，但单位成本高、产量小。流水线（大量）生产：标准化连续出产，单位成本低、效率高，但产品缺乏灵活性、难以按个别客户要求改变。","explain":"评分要点：①单件生产灵活性高、单位成本高；②流水线单位成本低、效率高；③流水线产品不灵活、单件产量小。能对比分析给满分。","tags":["operations","methods"],"xpReward":5 },
  { "id":"bus_q198","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"企业采用自动化设备代替人工，最直接的目的是？","type":"choice","options":["增加工资","提高生产率、降低长期单位成本","增加事故","减少产量"],"answer":"提高生产率、降低长期单位成本","explain":"自动化提高产出效率、减少对人工的依赖，长期降低单位成本。","tags":["operations","productivity"],"xpReward":10 },
  { "id":"bus_q199","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"下列哪一项属于「固定成本」？","type":"choice","options":["每件产品的包装材料","厂房的年租金","随产量增加的电费","计件工资"],"answer":"厂房的年租金","explain":"租金在短期内不随产量变化；材料、计件工资、超额电费随产量变动。","tags":["operations","costs"],"xpReward":10 },
  { "id":"bus_q200","exam_board":"CIE","subject":"business","chapter":"Operations","topicId":"bus_operations","question":"解释企业为什么要做生产选址决策，至少列出两个选址时要权衡的因素。","type":"essay","options":[],"answer":"选址影响长期成本、运输和市场可达性，一旦定下来很难更改。要权衡的因素包括：靠近原料还是靠近市场、劳动力成本与技能、交通与基础设施、土地租金、水电供应以及政府政策和环保要求。","explain":"评分要点：①选址影响长期成本且难以改变；②列出两个以上权衡因素（原料/市场/劳动力/交通/成本/政策）。","tags":["operations","location"],"xpReward":5 }
]);
